using System.Text.Json;using WAID.Application.Services;namespace WAID.Infrastructure.Persistence;public sealed class SqliteRepairRecommendationRepository(WaidDatabase database):IRepairRecommendationRepository{private static readonly JsonSerializerOptions Options=new(JsonSerializerDefaults.Web);public async Task SaveAsync(RepairRankingRun run,CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="INSERT INTO repair_recommendation_runs(id,generated_utc,ranking_version,run_json)VALUES($id,$time,$version,$json)";q.Parameters.AddWithValue("$id",run.Id.ToString());q.Parameters.AddWithValue("$time",run.GeneratedAtUtc.ToString("O"));q.Parameters.AddWithValue("$version",run.RankingVersion);q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(run,Options));await q.ExecuteNonQueryAsync(token);}public async Task<RepairRankingRun?> GetLatestAsync(CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT run_json FROM repair_recommendation_runs ORDER BY generated_utc DESC LIMIT 1";var json=await q.ExecuteScalarAsync(token) as string;return json is null?null:JsonSerializer.Deserialize<RepairRankingRun>(json,Options);}}